#!/usr/bin/env bash
# Prints the Homebrew formula (SylphxAI/homebrew-tap Formula/sylphx.rb) for a
# release, from the release's SHA256SUMS.
#   scripts/brew-formula.sh <version, e.g. 0.25.0> <SHA256SUMS file>
set -euo pipefail
v="$1" sums="$2"
sha() { awk -v f="sylphx-cli-$1" '$2 == f { print $1 }' "$sums" | grep -E '^[0-9a-f]{64}$' || { echo "no checksum for sylphx-cli-$1" >&2; exit 1; }; }
base="https://github.com/SylphxAI/sylphx-clients/releases/download/v$v"
cat <<RB
# Generated by SylphxAI/sylphx-clients scripts/brew-formula.sh for v$v.
class Sylphx < Formula
  desc "Command-line interface for the Sylphx platform"
  homepage "https://sylphx.com"
  license "MIT"

  on_macos do
    on_arm do
      url "$base/sylphx-cli-darwin-arm64"
      sha256 "$(sha darwin-arm64)"
    end
    on_intel do
      url "$base/sylphx-cli-darwin-x64"
      sha256 "$(sha darwin-x64)"
    end
  end

  on_linux do
    on_arm do
      url "$base/sylphx-cli-linux-arm64"
      sha256 "$(sha linux-arm64)"
    end
    on_intel do
      url "$base/sylphx-cli-linux-x64"
      sha256 "$(sha linux-x64)"
    end
  end

  def install
    bin.install Dir["sylphx-cli-*"].first => "sylphx"
  end

  test do
    assert_equal "sylphx #{version}", shell_output("#{bin}/sylphx --version").strip
  end
end
RB
